{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title",
        "intro_paragraph",
        "divider_1",
        "observed_impacts_heading",
        "observed_impacts_intro",
        "observed_impact_1_stack",
        "observed_impact_2_stack",
        "observed_impact_3_stack",
        "observed_impact_4_stack",
        "divider_2",
        "future_projections_heading",
        "future_projections_intro",
        "future_projection_1_stack",
        "future_projection_2_stack",
        "future_projection_3_stack",
        "future_projection_4_stack",
        "future_projection_5_stack",
        "future_projection_6_stack",
        "divider_3",
        "sources_heading",
        "source_button_1",
        "source_button_2"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "2023 IPCC Climate Report: Synthesis of Key Findings",
        "variant": "h2"
      },
      "children": []
    },
    "intro_paragraph": {
      "type": "Text",
      "props": {
        "text": "The Intergovernmental Panel on Climate Change (IPCC) 2023 Synthesis Report (AR6 SYR) consolidates the findings of its Sixth Assessment Cycle, providing a comprehensive overview of climate change science. It confirms that human activities are unequivocally causing global warming, leading to widespread and rapid changes in the atmosphere, ocean, cryosphere, and biosphere.",
        "variant": "body"
      },
      "children": []
    },
    "divider_1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "observed_impacts_heading": {
      "type": "Text",
      "props": {
        "text": "Observed Impacts of Climate Change",
        "variant": "h3"
      },
      "children": []
    },
    "observed_impacts_intro": {
      "type": "Text",
      "props": {
        "text": "The report highlights that observed changes are widespread, rapid, and intensifying, affecting every region across the globe.",
        "variant": "body"
      },
      "children": []
    },
    "observed_impact_1_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "observed_impact_1_label",
        "observed_impact_1_description"
      ]
    },
    "observed_impact_1_label": {
      "type": "Text",
      "props": {
        "text": "Global Warming:",
        "variant": "label"
      },
      "children": []
    },
    "observed_impact_1_description": {
      "type": "Text",
      "props": {
        "text": "Global surface temperature has risen by approximately 1.1°C since 1850-1900, with the most recent decade (2011-2020) being the warmest on record.",
        "variant": "body"
      },
      "children": []
    },
    "observed_impact_2_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "observed_impact_2_label",
        "observed_impact_2_description"
      ]
    },
    "observed_impact_2_label": {
      "type": "Text",
      "props": {
        "text": "Extreme Weather Events:",
        "variant": "label"
      },
      "children": []
    },
    "observed_impact_2_description": {
      "type": "Text",
      "props": {
        "text": "Frequency and intensity of extreme weather events (heatwaves, heavy precipitation, droughts, tropical cyclones) have increased in most regions.",
        "variant": "body"
      },
      "children": []
    },
    "observed_impact_3_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "observed_impact_3_label",
        "observed_impact_3_description"
      ]
    },
    "observed_impact_3_label": {
      "type": "Text",
      "props": {
        "text": "Sea Level Rise:",
        "variant": "label"
      },
      "children": []
    },
    "observed_impact_3_description": {
      "type": "Text",
      "props": {
        "text": "Global mean sea level has risen faster since 1900 than over any preceding century in at least the last 3,000 years, driven by thermal expansion and ice melt.",
        "variant": "body"
      },
      "children": []
    },
    "observed_impact_4_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "observed_impact_4_label",
        "observed_impact_4_description"
      ]
    },
    "observed_impact_4_label": {
      "type": "Text",
      "props": {
        "text": "Ecosystem Impacts:",
        "variant": "label"
      },
      "children": []
    },
    "observed_impact_4_description": {
      "type": "Text",
      "props": {
        "text": "Widespread and rapid changes in ecosystems, including species extinctions, shifts in geographical ranges, and altered seasonal timings.",
        "variant": "body"
      },
      "children": []
    },
    "divider_2": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "future_projections_heading": {
      "type": "Text",
      "props": {
        "text": "Future Projections and Risks",
        "variant": "h3"
      },
      "children": []
    },
    "future_projections_intro": {
      "type": "Text",
      "props": {
        "text": "Without deep, rapid, and sustained greenhouse gas emission reductions, global warming will exceed 1.5°C in the 21st century, leading to unavoidable increases in multiple climate hazards.",
        "variant": "body"
      },
      "children": []
    },
    "future_projection_1_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "future_projection_1_label",
        "future_projection_1_description"
      ]
    },
    "future_projection_1_label": {
      "type": "Text",
      "props": {
        "text": "Continued Warming:",
        "variant": "label"
      },
      "children": []
    },
    "future_projection_1_description": {
      "type": "Text",
      "props": {
        "text": "All projected scenarios show continued warming, with the 1.5°C global warming level likely to be reached in the near term (2021-2040).",
        "variant": "body"
      },
      "children": []
    },
    "future_projection_2_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "future_projection_2_label",
        "future_projection_2_description"
      ]
    },
    "future_projection_2_label": {
      "type": "Text",
      "props": {
        "text": "Increased Extremes:",
        "variant": "label"
      },
      "children": []
    },
    "future_projection_2_description": {
      "type": "Text",
      "props": {
        "text": "Further increases in the frequency and intensity of hot extremes, marine heatwaves, heavy precipitation, agricultural and ecological droughts, and intense tropical cyclones.",
        "variant": "body"
      },
      "children": []
    },
    "future_projection_3_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "future_projection_3_label",
        "future_projection_3_description"
      ]
    },
    "future_projection_3_label": {
      "type": "Text",
      "props": {
        "text": "Irreversible Changes:",
        "variant": "label"
      },
      "children": []
    },
    "future_projection_3_description": {
      "type": "Text",
      "props": {
        "text": "Some future changes, such as sea level rise, are irreversible over centuries to millennia.",
        "variant": "body"
      },
      "children": []
    },
    "future_projection_4_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "future_projection_4_label",
        "future_projection_4_description"
      ]
    },
    "future_projection_4_label": {
      "type": "Text",
      "props": {
        "text": "Food and Water Security:",
        "variant": "label"
      },
      "children": []
    },
    "future_projection_4_description": {
      "type": "Text",
      "props": {
        "text": "Risks to food security and water availability will intensify, particularly in vulnerable regions.",
        "variant": "body"
      },
      "children": []
    },
    "future_projection_5_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "future_projection_5_label",
        "future_projection_5_description"
      ]
    },
    "future_projection_5_label": {
      "type": "Text",
      "props": {
        "text": "Health Impacts:",
        "variant": "label"
      },
      "children": []
    },
    "future_projection_5_description": {
      "type": "Text",
      "props": {
        "text": "Increased risks to human health, including heat-related mortality and the spread of vector-borne diseases.",
        "variant": "body"
      },
      "children": []
    },
    "future_projection_6_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm"
      },
      "children": [
        "future_projection_6_label",
        "future_projection_6_description"
      ]
    },
    "future_projection_6_label": {
      "type": "Text",
      "props": {
        "text": "Economic Damages:",
        "variant": "label"
      },
      "children": []
    },
    "future_projection_6_description": {
      "type": "Text",
      "props": {
        "text": "Significant economic damages and disruptions to livelihoods are projected, disproportionately affecting the poor and vulnerable.",
        "variant": "body"
      },
      "children": []
    },
    "divider_3": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "source_button_1": {
      "type": "Button",
      "props": {
        "label": "IPCC AR6 Synthesis Report",
        "variant": "borderless"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ipcc.ch/report/ar6/syr/"
          }
        }
      }
    },
    "source_button_2": {
      "type": "Button",
      "props": {
        "label": "Summary for Policymakers",
        "variant": "borderless"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ipcc.ch/report/ar6/syr/resources/spm-headline-statements/"
          }
        }
      }
    }
  }
}
